class Handler {
  setNext(h) { this.next = h; return h; }
  handle(r) { return this.next ? this.next.handle(r) : null; }
}
class A extends Handler {
  handle(r) { return r.a ? 'a ok' : super.handle(r); }
}
const chain = new A();
chain.setNext(new Handler());
console.log(chain.handle({ a: true }));
